"""Migration of the Meridian CRM opportunity_pipeline workflow."""

from __future__ import annotations


def _numeric_value(value: object) -> float:
    """Coerce VRL numeric values, where empty values become zero."""
    if value is None or value == "":
        return 0.0
    if isinstance(value, bool):
        return float(value)
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _has_positive_amount(record: dict) -> bool:
    return _numeric_value(record.get("AMT", "")) > 0


def _close_date_is_not_sentinel(record: dict) -> bool:
    return record.get("CLOSE_DT", "") != "00000000"


def _has_lost_reason(record: dict) -> bool:
    value = record.get("LOST_RSN", "")
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity workflow transition."""
    transitions = (
        ("P", "qualify", _has_positive_amount, "Q", (("STAGE_PCT", "25"),), ("OPP_QUAL",), ()),
        ("Q", "advance", None, "N", (("STAGE_PCT", "60"),), (), ()),
        (
            "N",
            "close_won",
            _close_date_is_not_sentinel,
            "W",
            (("STAGE_PCT", "100"),),
            ("OPP_WON",),
            ("won_deal",),
        ),
        ("P", "close_lost", _has_lost_reason, "L", (("STAGE_PCT", "0"),), ("OPP_LOST",), ()),
        ("Q", "close_lost", _has_lost_reason, "L", (("STAGE_PCT", "0"),), ("OPP_LOST",), ()),
        ("N", "close_lost", _has_lost_reason, "L", (("STAGE_PCT", "0"),), ("OPP_LOST",), ()),
    )

    for from_state, transition_event, guard, to_state, sets, audits, notifies in transitions:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        updated_record = dict(record)
        for field, value in sets:
            updated_record[field] = value

        return {
            "state": to_state,
            "record": updated_record,
            "audits": list(audits),
            "notifies": list(notifies),
            "matched": True,
        }

    return {
        "state": state,
        "record": dict(record),
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
